var MURA_ALTE=[[0,0],[270.6,0],[270.7,1],[400.6,1],[403.2,1.5]];   // l'altezza a lavori finiti: come sale il cantiere fra il 271 e il 280 sta in js/mura.js (CANTIERE_MURA). Rialzate nel 401-403 (o già sotto Massenzio: discusso). 1 vale 7 m fuori terra («not more than 25 feet», Platner), 1,5 vale 12 m (da 6-8 ad almeno 10,5-15 m, it.wikipedia)

function interp(punti,x){
  if(x<=punti[0][0]) return punti[0][1];
  for(var i=1;i<punti.length;i++) if(x<=punti[i][0]){ var a=punti[i-1], b=punti[i]; return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0]); }
  return punti[punti.length-1][1];
}
/* Protagonisti per tappa: [nome, date, una riga]. Scritti il 22 novembre 2026 e riscontrati da un verificatore su enciclopedie e Wikidata (date in blocco, fatti voce per voce: 72 voci su 112 confermate, le altre corrette
   o rese più prudenti). Restano a memoria, senza una pagina aperta: Leone III a Paderborn nel 799, la malattia di Giustiniano durante la peste, Lattanzio sull'esito dell'editto dei prezzi.
   Dove gli studiosi divergono la riga lo dice (Erennio Etrusco, Tetrico, Zenobia, il rescritto di Onorio, la morte di Boezio, il pagamento di Gregorio Magno ad Agilulfo, la prima discesa di Pipino). */
